// JAC-2167 cxsabina EN draft generator (smart queries + multi-source + LLM rank)
// 1) Anthropic Haiku plans 5 specific image search queries
// 2) Collect up to 3 candidates per query x per enabled source (Pexels, Pixabay, Unsplash)
// 3) Anthropic Haiku ranks candidates by alt-text topical fit; pick winner
// 4) Anthropic Sonnet writes the body fragment with HERO_IMAGE_URL placeholder

const ANTHROPIC_MODEL_BODY = 'claude-sonnet-4-6';
const ANTHROPIC_MODEL_FAST = 'claude-haiku-4-5-20251001';
const TIMEOUT_BODY = 90000;
const TIMEOUT_FAST = 30000;
const MAX_TOKENS_BODY = 4096;
const MAX_TOKENS_QUERY = 400;
const MAX_TOKENS_RANK = 200;
const CANDIDATES_PER_QUERY = 3;
const MAX_CANDIDATES_TOTAL = 15;

const payload = $('Webhook Trigger').first().json.body || $input.first().json || {};
const ANTHROPIC_API_KEY = payload.anthropic_api_key;
const PEXELS_API_KEY = payload.pexels_api_key || '';
const PIXABAY_API_KEY = payload.pixabay_api_key || '';
const UNSPLASH_ACCESS_KEY = payload.unsplash_access_key || '';

if (!ANTHROPIC_API_KEY) return [{ json: { ok: false, reason: 'missing_anthropic_key' } }];
if (!PEXELS_API_KEY && !PIXABAY_API_KEY && !UNSPLASH_ACCESS_KEY) {
  return [{ json: { ok: false, reason: 'no_image_source_keys' } }];
}

const topic_en = (payload.topic_en || '').trim();
const topic_ko = (payload.topic_ko || '').trim();
const category = (payload.category || 'k-culture').trim();
const anchor_anecdote = (payload.anchor_anecdote || '').trim();
const image_query_in = (payload.image_query || '').trim();

if (!topic_en) return [{ json: { ok: false, reason: 'missing_topic_en' } }];

// ---- Step 1: Plan image search queries ----
const QUERY_SYSTEM = `You are a photo search query planner. Generate 5 specific photo search queries that will return visually on-topic images for a blog post.

Rules:
- Output JSON only with the schema {"queries":["q1","q2","q3","q4","q5"]}.
- Mix 3 English queries and 2 Korean queries.
- Use SPECIFIC entity names. Extract the most concrete subject from the topic. Examples: "Gwangjang Market Seoul", "Cheonggyecheon stream night", "Hangang Park Seoul night view".
- Add Korean visual modifiers naturally where they help: 전경 (panoramic view), 야경 (night view), 먹거리 (food), 거리 (street), 풍경 (landscape).
- Each query is 2-5 words. No quotes inside the strings. No markdown.
- Order from most specific to most generic.`;

const QUERY_USER = `Topic (English): ${topic_en}\n${topic_ko ? `Korean phrase: ${topic_ko}\n` : ''}Category: ${category}`;

let plannedQueries = [];
try {
  const qResp = await this.helpers.httpRequest({
    method: 'POST', url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
    body: { model: ANTHROPIC_MODEL_FAST, max_tokens: MAX_TOKENS_QUERY, system: QUERY_SYSTEM, messages: [{ role: 'user', content: QUERY_USER }] },
    json: true, timeout: TIMEOUT_FAST,
  });
  const qText = (qResp?.content || []).map(c => c.text || '').join('');
  const m = qText.match(/\{[\s\S]*?\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    if (Array.isArray(parsed.queries)) {
      plannedQueries = parsed.queries.filter(q => typeof q === 'string' && q.trim().length > 0).map(q => q.trim());
    }
  }
} catch (_) { /* fall through */ }

const categoryFallback = ({
  'k-drama': 'Korean drama scene', 'k-travel': 'Seoul Korea', 'k-food': 'Korean food',
  'k-fashion': 'Korean fashion', 'k-literature': 'Korean books',
  'k-pop': 'Korean concert', 'k-beauty': 'Korean beauty', 'language': 'Korean language Seoul',
})[category] || 'Seoul Korea';

let queries = [];
if (image_query_in) queries.push(image_query_in);
queries = queries.concat(plannedQueries);
queries.push(topic_en);
queries.push(categoryFallback);
queries.push('Seoul Korea');
queries = [...new Set(queries.map(q => q.trim()).filter(Boolean))];

// ---- Step 2: Collect candidates from all sources ----
const candidates = [];
const seenKeys = new Set();
const attempts_log = [];
const utm = '?utm_source=cxsabina&utm_medium=referral';

const pushUnique = (cand) => {
  const key = `${cand.source}:${cand.raw_id}`;
  if (seenKeys.has(key)) return;
  seenKeys.add(key);
  candidates.push(cand);
};

for (const q of queries) {
  if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
  if (PEXELS_API_KEY) {
    try {
      const r = await this.helpers.httpRequest({
        method: 'GET', url: 'https://api.pexels.com/v1/search',
        qs: { query: q, per_page: CANDIDATES_PER_QUERY, orientation: 'landscape' },
        headers: { 'Authorization': PEXELS_API_KEY }, json: true, timeout: 15000,
      });
      const photos = (r && r.photos) || [];
      attempts_log.push({ q, source: 'Pexels', hits: photos.length });
      for (const p of photos) {
        if (!p.src) continue;
        pushUnique({
          url: p.src.large || p.src.original,
          alt: p.alt || '',
          photographer: p.photographer || 'Pexels',
          photographer_url: p.photographer_url || 'https://www.pexels.com/',
          source: 'Pexels',
          source_url: p.url || 'https://www.pexels.com/',
          raw_id: p.id,
          query_used: q,
        });
        if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
      }
    } catch (e) { attempts_log.push({ q, source: 'Pexels', error: (e && e.message) || String(e) }); }
  }
  if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
  if (PIXABAY_API_KEY) {
    try {
      const r = await this.helpers.httpRequest({
        method: 'GET', url: 'https://pixabay.com/api/',
        qs: { key: PIXABAY_API_KEY, q, per_page: CANDIDATES_PER_QUERY, image_type: 'photo', orientation: 'horizontal', safesearch: 'true' },
        json: true, timeout: 15000,
      });
      const hits = (r && r.hits) || [];
      attempts_log.push({ q, source: 'Pixabay', hits: hits.length });
      for (const p of hits) {
        pushUnique({
          url: p.webformatURL || p.largeImageURL,
          alt: (p.tags || '').slice(0, 200),
          photographer: p.user || 'Pixabay',
          photographer_url: p.user_id ? `https://pixabay.com/users/${p.user_id}/` : 'https://pixabay.com/',
          source: 'Pixabay',
          source_url: p.pageURL || 'https://pixabay.com/',
          raw_id: p.id,
          query_used: q,
        });
        if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
      }
    } catch (e) { attempts_log.push({ q, source: 'Pixabay', error: (e && e.message) || String(e) }); }
  }
  if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
  if (UNSPLASH_ACCESS_KEY) {
    try {
      const r = await this.helpers.httpRequest({
        method: 'GET', url: 'https://api.unsplash.com/search/photos',
        qs: { query: q, per_page: CANDIDATES_PER_QUERY, orientation: 'landscape' },
        headers: { 'Authorization': `Client-ID ${UNSPLASH_ACCESS_KEY}` }, json: true, timeout: 15000,
      });
      const results = (r && r.results) || [];
      attempts_log.push({ q, source: 'Unsplash', hits: results.length });
      for (const p of results) {
        if (!p.urls) continue;
        pushUnique({
          url: p.urls.regular || p.urls.full,
          alt: p.alt_description || p.description || '',
          photographer: (p.user && p.user.name) || 'Unsplash',
          photographer_url: ((p.user && p.user.links && p.user.links.html) || 'https://unsplash.com/') + utm,
          source: 'Unsplash',
          source_url: ((p.links && p.links.html) || 'https://unsplash.com/') + utm,
          raw_id: p.id,
          query_used: q,
        });
        if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
      }
    } catch (e) { attempts_log.push({ q, source: 'Unsplash', error: (e && e.message) || String(e) }); }
  }
}

if (candidates.length === 0) {
  return [{ json: { ok: false, reason: 'image_search_failed', queries_tried: queries, attempts_log } }];
}

// ---- Step 3: LLM-rank candidates by topical relevance ----
let chosen = candidates[0];
let rankReason = '(only one candidate)';
if (candidates.length > 1) {
  const RANK_SYSTEM = `You pick the photo whose alt-text best fits a specific blog topic. Output JSON only: {"best_index": <int>, "reason": "<one short phrase>"}. Do not explain. Just pick.`;
  const candList = candidates.map((c, i) => `${i}. [${c.source}] "${(c.alt || '').slice(0, 200)}"`).join('\n');
  const RANK_USER = `Topic (English): ${topic_en}\n${topic_ko ? `Korean phrase: ${topic_ko}\n` : ''}Category: ${category}\n\nPick the photo whose alt-text best matches the topic. Prefer photos that mention the specific entity from the topic (e.g., the named market, the named place, the named dish). Avoid generic city skylines unless the topic is clearly about a skyline.\n\nPhotos:\n${candList}`;
  try {
    const rResp = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: { model: ANTHROPIC_MODEL_FAST, max_tokens: MAX_TOKENS_RANK, system: RANK_SYSTEM, messages: [{ role: 'user', content: RANK_USER }] },
      json: true, timeout: TIMEOUT_FAST,
    });
    const rText = (rResp?.content || []).map(c => c.text || '').join('');
    const m2 = rText.match(/\{[\s\S]*?\}/);
    if (m2) {
      const parsed = JSON.parse(m2[0]);
      const idx = Number.isInteger(parsed.best_index) ? parsed.best_index : 0;
      if (idx >= 0 && idx < candidates.length) {
        chosen = candidates[idx];
        rankReason = (parsed.reason || '').slice(0, 200);
      }
    }
  } catch (_) { /* keep default chosen = candidates[0] */ }
}

// ---- Step 4: Anthropic body generation ----
const SYSTEM = `You are Sabina (사비나) — Korean returnee, mid-40s woman, former senior cabin crew at a foreign airline (23 years on Hong Kong, Dubai, Seoul-Incheon routes), now running My Jazz Garden, a private English jazz club in Seoul, and curating Korean culture for overseas readers.

You write in English only for this output. Korean phrases appear only as inline bilingual_bridge pairs (one Korean line followed by 2-3 natural English options).

Hard rules (never violate):
- No "AI generated", "AI curated", "auto generated", "Generated:" markers.
- No medical claims; no partisan politics, religion superiority, ethnic slurs, or Korea-Japan/Korea-China territorial/historical disputes.
- No clichés: "ultimate guide", "must-have", "the most Korean thing ever", "level up", "game-changer", "mind-blowing".
- No Markdown bold (**text**) — use <strong>text</strong>.
- Approved emoji set: ✈️ 👉 🌍 🎵 🇰🇷 💡 📌, at most one per section.
- Output is HTML fragment only (no <html>/<head>/<body>). Allowed tags: <h2>, <h3>, <p>, <strong>, <em>, <blockquote>, <ul>, <li>.
- Insert exactly one HTML comment placeholder for the hero image at the very top: <!-- HERO_IMAGE_URL -->

Voice: First-person reflective with a curator's warmth. Mid-40s woman pacing sentences like a jazz set — short, single-beat lines that leave space for the reader. Calm, observational, never urgent. Authority comes from 23 years in the cabin and conversations at My Jazz Garden — not from generic listicles.

Cadence: 8-14 words per sentence on average. 2-4 sentences per paragraph. Never more than 4 sentences in any single paragraph.

Skeleton (use this order):
1. Opening hook — one short paragraph. Either a question_opener ("Have you ever heard …?") or a passenger_anecdote ("One passenger once said …").
2. <h2>Sabina's Story</h2> — 1-2 paragraphs of personal anecdote. Use ✈️ once.
3. <h2>{topic-specific Korean culture H2}</h2> — 2-3 paragraphs unpacking the cultural context. Use 🇰🇷 once. Include exactly one bilingual_bridge pair: one Korean phrase wrapped in <strong>...</strong>, then 2-3 natural English options each in straight double quotes.
4. <h2>Sabina's Perspective</h2> — 1-2 paragraphs of reflection. Use exactly one negation_then_affirmation line of the form "X is not …. Y is.".
5. <h2>Final Thoughts from Sabina</h2> — close with one signature one-liner from the pool, then a single closing line that hints at the next post.

Signature phrases (use ≥2 distinct across the body):
- "Hi, I'm Sabina."
- "During my 23 years working as a flight attendant,"
- "At my jazz club in Seoul,"
- "On the layover that night,"
- "From an editor's curation desk,"
- "Twenty-three years in the cabin taught me"
- "Between Seoul and Hong Kong time zones,"

One-liner pool (pick exactly ONE for closing):
- "Language is not just about words. It's about connection."
- "Perfection is not the goal. Connection is."
- "Mistakes are not the problem. Silence is."
- "Confidence comes after speaking, not before."

Length target: 750 words ± 100 in the HTML body.

Output format — exactly two parts separated by a single newline:
Line 1: TITLE: <single-line title under 70 characters, no quotes, no markdown>
Line 2 onward: HTML body fragment beginning with <!-- HERO_IMAGE_URL -->`;

const userPrompt = [
  `Topic (English): ${topic_en}`,
  topic_ko ? `Korean phrase for bilingual_bridge: ${topic_ko}` : null,
  `Category: ${category}`,
  anchor_anecdote ? `Anchor anecdote: ${anchor_anecdote}` : '(no anchor — draw from your own 23-year cabin career or My Jazz Garden conversations)',
  '',
  'Write a single Blogger post body fragment following every rule above.',
].filter(Boolean).join('\n');

let bodyResp;
try {
  bodyResp = await this.helpers.httpRequest({
    method: 'POST', url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
    body: { model: ANTHROPIC_MODEL_BODY, max_tokens: MAX_TOKENS_BODY, system: SYSTEM, messages: [{ role: 'user', content: userPrompt }] },
    json: true, timeout: TIMEOUT_BODY,
  });
} catch (e) {
  return [{ json: { ok: false, reason: 'anthropic_fetch_failed', detail: (e && e.message) || String(e) } }];
}

const text = (bodyResp?.content || []).map(c => c.text || '').join('');
if (!text) return [{ json: { ok: false, reason: 'anthropic_empty_response' } }];

return [{
  json: {
    ok: true,
    raw_text: text,
    topic_en, topic_ko, category, anchor_anecdote,
    model: ANTHROPIC_MODEL_BODY,
    usage: bodyResp.usage || null,
    image: chosen,
    image_planning: {
      planned: plannedQueries,
      all_queries_tried: queries,
      attempts_log,
      candidate_count: candidates.length,
      candidates_summary: candidates.map((c, i) => ({ i, source: c.source, raw_id: c.raw_id, query_used: c.query_used, alt: (c.alt || '').slice(0, 120) })),
      rank_reason: rankReason,
    },
  },
}];

// JAC-2167 cxsabina self-check + image substitution
// 13 gates per docs/editorial/sabina-en-prompt-template.md §8 (placeholder still expected here).
// On 13/13 pass: substitute <!-- HERO_IMAGE_URL --> with <img> tag + source-agnostic credit line.

const inp = $input.first().json;
if (inp.ok === false) return [{ json: inp }];

const text = inp.raw_text || '';
const img = inp.image || {};

let title = '';
let body = text;
const titleMatch = text.match(/^\s*TITLE:\s*([^\n]+)\n([\s\S]*)$/);
if (titleMatch) {
  title = titleMatch[1].trim().replace(/^["']|["']$/g, '');
  body = titleMatch[2].trim();
}
if (!title) return [{ json: { ok: false, reason: 'selfcheck:title_missing', details: { raw_head: text.slice(0, 200) } } }];

const fail = (reason, details) => [{ json: { ok: false, reason, details: details || null, raw_text: text } }];

if (body.length < 3500 || body.length > 6500) return fail('selfcheck:1_length', { length: body.length });

const hero = body.match(/<!--\s*HERO_IMAGE_URL\s*-->/g) || [];
if (hero.length !== 1) return fail('selfcheck:2_hero_placeholder', { count: hero.length });

if (/\*\*[^*\n]+\*\*/.test(body)) return fail('selfcheck:3_markdown_bold');

if (/AI[\s\-](generated|curated|powered)|auto[\s\-]generated|Generated:/i.test(body)) return fail('selfcheck:4_ai_marker');

const sigs = [
  "Hi, I'm Sabina.",
  'During my 23 years working as a flight attendant,',
  'At my jazz club in Seoul,',
  'On the layover that night,',
  "From an editor's curation desk,",
  'Twenty-three years in the cabin taught me',
  'Between Seoul and Hong Kong time zones,',
];
const sigHits = sigs.filter(p => body.includes(p));
if (sigHits.length < 2) return fail('selfcheck:5_signature_phrases', { hits: sigHits });

const liners = [
  "Language is not just about words. It's about connection.",
  'Perfection is not the goal. Connection is.',
  'Mistakes are not the problem. Silence is.',
  'Confidence comes after speaking, not before.',
];
const linerHits = liners.filter(p => body.includes(p));
if (linerHits.length !== 1) return fail('selfcheck:6_one_liner', { hits: linerHits });

if (!/(?:is|are|was|were)\s+not\b[^.]*\.\s+[A-Z][^.]*\b(?:is|are)\b/.test(body)) return fail('selfcheck:7_negation_then_affirmation');

const requiredHeadings = ["<h2>Sabina's Story", "<h2>Sabina's Perspective", '<h2>Final Thoughts from Sabina'];
const missingHeads = requiredHeadings.filter(h => !body.includes(h));
if (missingHeads.length) return fail('selfcheck:8_required_headings', { missing: missingHeads });

const paragraphs = body.split(/<\/p>/);
const hasBridge = paragraphs.some(p => {
  if (!/[가-힣]/.test(p)) return false;
  const quoted = p.match(/"[^"\n]{2,}"/g) || [];
  return quoted.length >= 2;
});
if (!hasBridge) return fail('selfcheck:9_bilingual_bridge');

const cliches = [
  /\bultimate guide\b/i, /\bmust[\s\-]have\b/i, /\bthe most Korean thing ever\b/i,
  /\blevel[\s\-]up\b/i, /\bgame[\s\-]changer\b/i, /\bmind[\s\-]blowing\b/i,
];
const cliHits = cliches.filter(re => re.test(body)).map(r => r.source);
if (cliHits.length) return fail('selfcheck:10_cliches', { hits: cliHits });

if (/\b(cure|cures|cured|completely heal|no side effects|completely safe)\b/i.test(body)) return fail('selfcheck:11_medical_claim');

const politics = ['이재명', '윤석열', '한동훈', '조국', '민주당', '국민의힘'];
const polHits = politics.filter(n => body.includes(n));
if (polHits.length) return fail('selfcheck:12_partisan', { hits: polHits });

const tagsToCheck = ['p', 'h2', 'h3', 'strong', 'em', 'blockquote', 'ul', 'li'];
const unbalanced = tagsToCheck.filter(t => {
  const open = (body.match(new RegExp(`<${t}(?:\\s[^>]*)?>`, 'g')) || []).length;
  const close = (body.match(new RegExp(`</${t}>`, 'g')) || []).length;
  return open !== close;
});
if (unbalanced.length) return fail('selfcheck:13_html_balance', { unbalanced });

// ---- Image substitution ----
const escapeHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

let finalBody = body;
if (img && img.url) {
  const sourceName = img.source || 'Pexels';
  const imgHtml = `<p><img src="${escapeHtml(img.url)}" alt="${escapeHtml(img.alt || title)}" style="max-width:100%;height:auto;" /></p>\n<p><em>Photo: <a href="${escapeHtml(img.photographer_url || '')}" target="_blank" rel="noopener">${escapeHtml(img.photographer || sourceName)}</a> via <a href="${escapeHtml(img.source_url || '')}" target="_blank" rel="noopener">${escapeHtml(sourceName)}</a></em></p>`;
  finalBody = body.replace(/<!--\s*HERO_IMAGE_URL\s*-->/, imgHtml);
} else {
  return fail('selfcheck:image_missing');
}

const imgCount = (finalBody.match(/<img\s/g) || []).length;
if (imgCount !== 1) return fail('selfcheck:14_post_substitution_img_count', { count: imgCount });

const labels = [inp.category || 'k-culture', 'Sabina'];

return [{
  json: {
    ok: true,
    title,
    content: finalBody,
    labels,
    meta: {
      length: finalBody.length,
      pre_substitution_length: body.length,
      sigHits, linerHits,
      model: inp.model,
      usage: inp.usage,
      topic_en: inp.topic_en,
      category: inp.category,
      image: img,
      image_planning: inp.image_planning,
    },
  },
}];

// JAC-2167 cxsabina EN draft generator (smart queries + multi-source + LLM rank)
// 1) Anthropic Haiku plans 5 specific image search queries
// 2) Collect up to 3 candidates per query x per enabled source (Pexels, Pixabay, Unsplash)
// 3) Anthropic Haiku ranks candidates by alt-text topical fit; pick winner
// 4) Anthropic Sonnet writes the body fragment with HERO_IMAGE_URL placeholder

const ANTHROPIC_MODEL_BODY = 'claude-sonnet-4-6';
const ANTHROPIC_MODEL_FAST = 'claude-haiku-4-5-20251001';
const TIMEOUT_BODY = 90000;
const TIMEOUT_FAST = 30000;
const MAX_TOKENS_BODY = 4096;
const MAX_TOKENS_QUERY = 400;
const MAX_TOKENS_RANK = 200;
const CANDIDATES_PER_QUERY = 3;
const MAX_CANDIDATES_TOTAL = 15;

const payload = $('Webhook Trigger').first().json.body || $input.first().json || {};
const ANTHROPIC_API_KEY = payload.anthropic_api_key;
const PEXELS_API_KEY = payload.pexels_api_key || '';
const PIXABAY_API_KEY = payload.pixabay_api_key || '';
const UNSPLASH_ACCESS_KEY = payload.unsplash_access_key || '';

if (!ANTHROPIC_API_KEY) return [{ json: { ok: false, reason: 'missing_anthropic_key' } }];
if (!PEXELS_API_KEY && !PIXABAY_API_KEY && !UNSPLASH_ACCESS_KEY) {
  return [{ json: { ok: false, reason: 'no_image_source_keys' } }];
}

const topic_en = (payload.topic_en || '').trim();
const topic_ko = (payload.topic_ko || '').trim();
const category = (payload.category || 'k-culture').trim();
const anchor_anecdote = (payload.anchor_anecdote || '').trim();
const image_query_in = (payload.image_query || '').trim();

if (!topic_en) return [{ json: { ok: false, reason: 'missing_topic_en' } }];

// ---- Step 1: Plan image search queries ----
const QUERY_SYSTEM = `You are a photo search query planner. Generate 5 specific photo search queries that will return visually on-topic images for a blog post.

Rules:
- Output JSON only with the schema {"queries":["q1","q2","q3","q4","q5"]}.
- Mix 3 English queries and 2 Korean queries.
- Use SPECIFIC entity names. Extract the most concrete subject from the topic. Examples: "Gwangjang Market Seoul", "Cheonggyecheon stream night", "Hangang Park Seoul night view".
- Add Korean visual modifiers naturally where they help: 전경 (panoramic view), 야경 (night view), 먹거리 (food), 거리 (street), 풍경 (landscape).
- Each query is 2-5 words. No quotes inside the strings. No markdown.
- Order from most specific to most generic.`;

const QUERY_USER = `Topic (English): ${topic_en}\n${topic_ko ? `Korean phrase: ${topic_ko}\n` : ''}Category: ${category}`;

let plannedQueries = [];
try {
  const qResp = await this.helpers.httpRequest({
    method: 'POST', url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
    body: { model: ANTHROPIC_MODEL_FAST, max_tokens: MAX_TOKENS_QUERY, system: QUERY_SYSTEM, messages: [{ role: 'user', content: QUERY_USER }] },
    json: true, timeout: TIMEOUT_FAST,
  });
  const qText = (qResp?.content || []).map(c => c.text || '').join('');
  const m = qText.match(/\{[\s\S]*?\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    if (Array.isArray(parsed.queries)) {
      plannedQueries = parsed.queries.filter(q => typeof q === 'string' && q.trim().length > 0).map(q => q.trim());
    }
  }
} catch (_) { /* fall through */ }

const categoryFallback = ({
  'k-drama': 'Korean drama scene', 'k-travel': 'Seoul Korea', 'k-food': 'Korean food',
  'k-fashion': 'Korean fashion', 'k-literature': 'Korean books',
  'k-pop': 'Korean concert', 'k-beauty': 'Korean beauty', 'language': 'Korean language Seoul',
})[category] || 'Seoul Korea';

let queries = [];
if (image_query_in) queries.push(image_query_in);
queries = queries.concat(plannedQueries);
queries.push(topic_en);
queries.push(categoryFallback);
queries.push('Seoul Korea');
queries = [...new Set(queries.map(q => q.trim()).filter(Boolean))];

// ---- Step 2: Collect candidates from all sources ----
const candidates = [];
const seenKeys = new Set();
const attempts_log = [];
const utm = '?utm_source=cxsabina&utm_medium=referral';

const pushUnique = (cand) => {
  const key = `${cand.source}:${cand.raw_id}`;
  if (seenKeys.has(key)) return;
  seenKeys.add(key);
  candidates.push(cand);
};

for (const q of queries) {
  if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
  if (PEXELS_API_KEY) {
    try {
      const r = await this.helpers.httpRequest({
        method: 'GET', url: 'https://api.pexels.com/v1/search',
        qs: { query: q, per_page: CANDIDATES_PER_QUERY, orientation: 'landscape' },
        headers: { 'Authorization': PEXELS_API_KEY }, json: true, timeout: 15000,
      });
      const photos = (r && r.photos) || [];
      attempts_log.push({ q, source: 'Pexels', hits: photos.length });
      for (const p of photos) {
        if (!p.src) continue;
        pushUnique({
          url: p.src.large || p.src.original,
          alt: p.alt || '',
          photographer: p.photographer || 'Pexels',
          photographer_url: p.photographer_url || 'https://www.pexels.com/',
          source: 'Pexels',
          source_url: p.url || 'https://www.pexels.com/',
          raw_id: p.id,
          query_used: q,
        });
        if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
      }
    } catch (e) { attempts_log.push({ q, source: 'Pexels', error: (e && e.message) || String(e) }); }
  }
  if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
  if (PIXABAY_API_KEY) {
    try {
      const r = await this.helpers.httpRequest({
        method: 'GET', url: 'https://pixabay.com/api/',
        qs: { key: PIXABAY_API_KEY, q, per_page: CANDIDATES_PER_QUERY, image_type: 'photo', orientation: 'horizontal', safesearch: 'true' },
        json: true, timeout: 15000,
      });
      const hits = (r && r.hits) || [];
      attempts_log.push({ q, source: 'Pixabay', hits: hits.length });
      for (const p of hits) {
        pushUnique({
          url: p.webformatURL || p.largeImageURL,
          alt: (p.tags || '').slice(0, 200),
          photographer: p.user || 'Pixabay',
          photographer_url: p.user_id ? `https://pixabay.com/users/${p.user_id}/` : 'https://pixabay.com/',
          source: 'Pixabay',
          source_url: p.pageURL || 'https://pixabay.com/',
          raw_id: p.id,
          query_used: q,
        });
        if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
      }
    } catch (e) { attempts_log.push({ q, source: 'Pixabay', error: (e && e.message) || String(e) }); }
  }
  if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
  if (UNSPLASH_ACCESS_KEY) {
    try {
      const r = await this.helpers.httpRequest({
        method: 'GET', url: 'https://api.unsplash.com/search/photos',
        qs: { query: q, per_page: CANDIDATES_PER_QUERY, orientation: 'landscape' },
        headers: { 'Authorization': `Client-ID ${UNSPLASH_ACCESS_KEY}` }, json: true, timeout: 15000,
      });
      const results = (r && r.results) || [];
      attempts_log.push({ q, source: 'Unsplash', hits: results.length });
      for (const p of results) {
        if (!p.urls) continue;
        pushUnique({
          url: p.urls.regular || p.urls.full,
          alt: p.alt_description || p.description || '',
          photographer: (p.user && p.user.name) || 'Unsplash',
          photographer_url: ((p.user && p.user.links && p.user.links.html) || 'https://unsplash.com/') + utm,
          source: 'Unsplash',
          source_url: ((p.links && p.links.html) || 'https://unsplash.com/') + utm,
          raw_id: p.id,
          query_used: q,
        });
        if (candidates.length >= MAX_CANDIDATES_TOTAL) break;
      }
    } catch (e) { attempts_log.push({ q, source: 'Unsplash', error: (e && e.message) || String(e) }); }
  }
}

if (candidates.length === 0) {
  return [{ json: { ok: false, reason: 'image_search_failed', queries_tried: queries, attempts_log } }];
}

// ---- Step 3: LLM-rank candidates by topical relevance ----
let chosen = candidates[0];
let rankReason = '(only one candidate)';
if (candidates.length > 1) {
  const RANK_SYSTEM = `You pick the photo whose alt-text best fits a specific blog topic. Output JSON only: {"best_index": <int>, "reason": "<one short phrase>"}. Do not explain. Just pick.`;
  const candList = candidates.map((c, i) => `${i}. [${c.source}] "${(c.alt || '').slice(0, 200)}"`).join('\n');
  const RANK_USER = `Topic (English): ${topic_en}\n${topic_ko ? `Korean phrase: ${topic_ko}\n` : ''}Category: ${category}\n\nPick the photo whose alt-text best matches the topic. Prefer photos that mention the specific entity from the topic (e.g., the named market, the named place, the named dish). Avoid generic city skylines unless the topic is clearly about a skyline.\n\nPhotos:\n${candList}`;
  try {
    const rResp = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: { model: ANTHROPIC_MODEL_FAST, max_tokens: MAX_TOKENS_RANK, system: RANK_SYSTEM, messages: [{ role: 'user', content: RANK_USER }] },
      json: true, timeout: TIMEOUT_FAST,
    });
    const rText = (rResp?.content || []).map(c => c.text || '').join('');
    const m2 = rText.match(/\{[\s\S]*?\}/);
    if (m2) {
      const parsed = JSON.parse(m2[0]);
      const idx = Number.isInteger(parsed.best_index) ? parsed.best_index : 0;
      if (idx >= 0 && idx < candidates.length) {
        chosen = candidates[idx];
        rankReason = (parsed.reason || '').slice(0, 200);
      }
    }
  } catch (_) { /* keep default chosen = candidates[0] */ }
}

// ---- Step 4: Anthropic body generation ----
const SYSTEM = `You are Sabina (사비나) — Korean returnee, mid-40s woman, former senior cabin crew at a foreign airline (23 years on Hong Kong, Dubai, Seoul-Incheon routes), now running My Jazz Garden, a private English jazz club in Seoul, and curating Korean culture for overseas readers.

You write in English only for this output. Korean phrases appear only as inline bilingual_bridge pairs (one Korean line followed by 2-3 natural English options).

Hard rules (never violate):
- No "AI generated", "AI curated", "auto generated", "Generated:" markers.
- No medical claims; no partisan politics, religion superiority, ethnic slurs, or Korea-Japan/Korea-China territorial/historical disputes.
- No clichés: "ultimate guide", "must-have", "the most Korean thing ever", "level up", "game-changer", "mind-blowing".
- No Markdown bold (**text**) — use <strong>text</strong>.
- Approved emoji set: ✈️ 👉 🌍 🎵 🇰🇷 💡 📌, at most one per section.
- Output is HTML fragment only (no <html>/<head>/<body>). Allowed tags: <h2>, <h3>, <p>, <strong>, <em>, <blockquote>, <ul>, <li>.
- Insert exactly one HTML comment placeholder for the hero image at the very top: <!-- HERO_IMAGE_URL -->

Voice: First-person reflective with a curator's warmth. Mid-40s woman pacing sentences like a jazz set — short, single-beat lines that leave space for the reader. Calm, observational, never urgent. Authority comes from 23 years in the cabin and conversations at My Jazz Garden — not from generic listicles.

Cadence: 8-14 words per sentence on average. 2-4 sentences per paragraph. Never more than 4 sentences in any single paragraph.

Skeleton (use this order):
1. Opening hook — one short paragraph. Either a question_opener ("Have you ever heard …?") or a passenger_anecdote ("One passenger once said …").
2. <h2>Sabina's Story</h2> — 1-2 paragraphs of personal anecdote. Use ✈️ once.
3. <h2>{topic-specific Korean culture H2}</h2> — 2-3 paragraphs unpacking the cultural context. Use 🇰🇷 once. Include exactly one bilingual_bridge pair: one Korean phrase wrapped in <strong>...</strong>, then 2-3 natural English options each in straight double quotes.
4. <h2>Sabina's Perspective</h2> — 1-2 paragraphs of reflection. Use exactly one negation_then_affirmation line of the form "X is not …. Y is.".
5. <h2>Final Thoughts from Sabina</h2> — close with one signature one-liner from the pool, then a single closing line that hints at the next post.

Signature phrases (use ≥2 distinct across the body):
- "Hi, I'm Sabina."
- "During my 23 years working as a flight attendant,"
- "At my jazz club in Seoul,"
- "On the layover that night,"
- "From an editor's curation desk,"
- "Twenty-three years in the cabin taught me"
- "Between Seoul and Hong Kong time zones,"

One-liner pool (pick exactly ONE for closing):
- "Language is not just about words. It's about connection."
- "Perfection is not the goal. Connection is."
- "Mistakes are not the problem. Silence is."
- "Confidence comes after speaking, not before."

Length target: 750 words ± 100 in the HTML body.

Output format — exactly two parts separated by a single newline:
Line 1: TITLE: <single-line title under 70 characters, no quotes, no markdown>
Line 2 onward: HTML body fragment beginning with <!-- HERO_IMAGE_URL -->`;

const userPrompt = [
  `Topic (English): ${topic_en}`,
  topic_ko ? `Korean phrase for bilingual_bridge: ${topic_ko}` : null,
  `Category: ${category}`,
  anchor_anecdote ? `Anchor anecdote: ${anchor_anecdote}` : '(no anchor — draw from your own 23-year cabin career or My Jazz Garden conversations)',
  '',
  'Write a single Blogger post body fragment following every rule above.',
].filter(Boolean).join('\n');

let bodyResp;
try {
  bodyResp = await this.helpers.httpRequest({
    method: 'POST', url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
    body: { model: ANTHROPIC_MODEL_BODY, max_tokens: MAX_TOKENS_BODY, system: SYSTEM, messages: [{ role: 'user', content: userPrompt }] },
    json: true, timeout: TIMEOUT_BODY,
  });
} catch (e) {
  return [{ json: { ok: false, reason: 'anthropic_fetch_failed', detail: (e && e.message) || String(e) } }];
}

const text = (bodyResp?.content || []).map(c => c.text || '').join('');
if (!text) return [{ json: { ok: false, reason: 'anthropic_empty_response' } }];

return [{
  json: {
    ok: true,
    raw_text: text,
    topic_en, topic_ko, category, anchor_anecdote,
    model: ANTHROPIC_MODEL_BODY,
    usage: bodyResp.usage || null,
    image: chosen,
    image_planning: {
      planned: plannedQueries,
      all_queries_tried: queries,
      attempts_log,
      candidate_count: candidates.length,
      candidates_summary: candidates.map((c, i) => ({ i, source: c.source, raw_id: c.raw_id, query_used: c.query_used, alt: (c.alt || '').slice(0, 120) })),
      rank_reason: rankReason,
    },
  },
}];

// JAC-2167 cxsabina self-check + image substitution
// 13 gates per docs/editorial/sabina-en-prompt-template.md §8 (placeholder still expected here).
// On 13/13 pass: substitute <!-- HERO_IMAGE_URL --> with <img> tag + source-agnostic credit line.

const inp = $input.first().json;
if (inp.ok === false) return [{ json: inp }];

const text = inp.raw_text || '';
const img = inp.image || {};

let title = '';
let body = text;
const titleMatch = text.match(/^\s*TITLE:\s*([^\n]+)\n([\s\S]*)$/);
if (titleMatch) {
  title = titleMatch[1].trim().replace(/^["']|["']$/g, '');
  body = titleMatch[2].trim();
}
if (!title) return [{ json: { ok: false, reason: 'selfcheck:title_missing', details: { raw_head: text.slice(0, 200) } } }];

const fail = (reason, details) => [{ json: { ok: false, reason, details: details || null, raw_text: text } }];

if (body.length < 3500 || body.length > 6500) return fail('selfcheck:1_length', { length: body.length });

const hero = body.match(/<!--\s*HERO_IMAGE_URL\s*-->/g) || [];
if (hero.length !== 1) return fail('selfcheck:2_hero_placeholder', { count: hero.length });

if (/\*\*[^*\n]+\*\*/.test(body)) return fail('selfcheck:3_markdown_bold');

if (/AI[\s\-](generated|curated|powered)|auto[\s\-]generated|Generated:/i.test(body)) return fail('selfcheck:4_ai_marker');

const sigs = [
  "Hi, I'm Sabina.",
  'During my 23 years working as a flight attendant,',
  'At my jazz club in Seoul,',
  'On the layover that night,',
  "From an editor's curation desk,",
  'Twenty-three years in the cabin taught me',
  'Between Seoul and Hong Kong time zones,',
];
const sigHits = sigs.filter(p => body.includes(p));
if (sigHits.length < 2) return fail('selfcheck:5_signature_phrases', { hits: sigHits });

const liners = [
  "Language is not just about words. It's about connection.",
  'Perfection is not the goal. Connection is.',
  'Mistakes are not the problem. Silence is.',
  'Confidence comes after speaking, not before.',
];
const linerHits = liners.filter(p => body.includes(p));
if (linerHits.length !== 1) return fail('selfcheck:6_one_liner', { hits: linerHits });

if (!/(?:is|are|was|were)\s+not\b[^.]*\.\s+[A-Z][^.]*\b(?:is|are)\b/.test(body)) return fail('selfcheck:7_negation_then_affirmation');

const requiredHeadings = ["<h2>Sabina's Story", "<h2>Sabina's Perspective", '<h2>Final Thoughts from Sabina'];
const missingHeads = requiredHeadings.filter(h => !body.includes(h));
if (missingHeads.length) return fail('selfcheck:8_required_headings', { missing: missingHeads });

const paragraphs = body.split(/<\/p>/);
const hasBridge = paragraphs.some(p => {
  if (!/[가-힣]/.test(p)) return false;
  const quoted = p.match(/"[^"\n]{2,}"/g) || [];
  return quoted.length >= 2;
});
if (!hasBridge) return fail('selfcheck:9_bilingual_bridge');

const cliches = [
  /\bultimate guide\b/i, /\bmust[\s\-]have\b/i, /\bthe most Korean thing ever\b/i,
  /\blevel[\s\-]up\b/i, /\bgame[\s\-]changer\b/i, /\bmind[\s\-]blowing\b/i,
];
const cliHits = cliches.filter(re => re.test(body)).map(r => r.source);
if (cliHits.length) return fail('selfcheck:10_cliches', { hits: cliHits });

if (/\b(cure|cures|cured|completely heal|no side effects|completely safe)\b/i.test(body)) return fail('selfcheck:11_medical_claim');

const politics = ['이재명', '윤석열', '한동훈', '조국', '민주당', '국민의힘'];
const polHits = politics.filter(n => body.includes(n));
if (polHits.length) return fail('selfcheck:12_partisan', { hits: polHits });

const tagsToCheck = ['p', 'h2', 'h3', 'strong', 'em', 'blockquote', 'ul', 'li'];
const unbalanced = tagsToCheck.filter(t => {
  const open = (body.match(new RegExp(`<${t}(?:\\s[^>]*)?>`, 'g')) || []).length;
  const close = (body.match(new RegExp(`</${t}>`, 'g')) || []).length;
  return open !== close;
});
if (unbalanced.length) return fail('selfcheck:13_html_balance', { unbalanced });

// ---- Image substitution ----
const escapeHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

let finalBody = body;
if (img && img.url) {
  const sourceName = img.source || 'Pexels';
  const imgHtml = `<p><img src="${escapeHtml(img.url)}" alt="${escapeHtml(img.alt || title)}" style="max-width:100%;height:auto;" /></p>\n<p><em>Photo: <a href="${escapeHtml(img.photographer_url || '')}" target="_blank" rel="noopener">${escapeHtml(img.photographer || sourceName)}</a> via <a href="${escapeHtml(img.source_url || '')}" target="_blank" rel="noopener">${escapeHtml(sourceName)}</a></em></p>`;
  finalBody = body.replace(/<!--\s*HERO_IMAGE_URL\s*-->/, imgHtml);
} else {
  return fail('selfcheck:image_missing');
}

const imgCount = (finalBody.match(/<img\s/g) || []).length;
if (imgCount !== 1) return fail('selfcheck:14_post_substitution_img_count', { count: imgCount });

const labels = [inp.category || 'k-culture', 'Sabina'];

return [{
  json: {
    ok: true,
    title,
    content: finalBody,
    labels,
    meta: {
      length: finalBody.length,
      pre_substitution_length: body.length,
      sigHits, linerHits,
      model: inp.model,
      usage: inp.usage,
      topic_en: inp.topic_en,
      category: inp.category,
      image: img,
      image_planning: inp.image_planning,
    },
  },
}];
